5: class DashboardPage extends StatefulWidget {
6:   const DashboardPage({super.key});
7: 
8:   @override
9:   State<DashboardPage> createState() => _DashboardPageState();
10: }
11: 
12: class _DashboardPageState extends State<DashboardPage> with SingleTickerProviderStateMixin {
13:   late final AnimationController _fadeController;
14: 
15:   late Future<void> _dashboardFuture;
16: 
17:   List<CurrencyModel> _currencies = [];
18:   List<NewsModel> _newsItems = [];
19: 
20:   @override
21:   void initState() {
22:     super.initState();
23:     _initAnimation();
24:     _initData();
25:   }
26: 
27:   @override
28:   void dispose() {
29:     _fadeController.dispose();
30:     super.dispose();
31:   }
32: 
33:   void _initAnimation() {
34:     _fadeController = AnimationController(
35:       duration: const Duration(milliseconds: 400),
36:       vsync: this,
37:     );
38:   }
39: 
40:   void _initData() {
41:     final currencyRepository = context.read<CurrencyRepository>();
42:     final newsRepository = context.read<NewsRepository>();
43: 
44:     _dashboardFuture = Future.wait([
45:       currencyRepository.fetchRates(const CurrencyPageRequest()),
46:       newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
47:     ]).then((List<dynamic> results) {
48:       setState(() {
49:         _currencies = (results[0] as CurrencyPage).items;
50:         _newsItems = results[1] as List<NewsModel>;
51: 
52:         currencyRepository.saveCurrencyList(_currencies);
53:       });
54: 
55:       _fadeController.forward();
56:     }).catchError((Object error) {
57:       debugPrint('Dashboard load error: $error');
58:       setState(() {
59:         _currencies = [];
60:         _newsItems = [];
61:       });
62:     });
63:   }
64: 
65:   List<Widget> _buildMixedList() {
66:     final List<Widget> items = <Widget>[];
67: 
68:     if (_currencies.isNotEmpty) {
69:       items.add(
70:         Padding(
71:           padding: const EdgeInsets.only(top: 8, bottom: 4),
72:           child: Text(
73:             context.loc.currencies,
74:             style: context.fonts.semiBold12.copyWith(color: context.colors.tin),
75:           ),
76:         ),
77:       );
78:     }
79: 
80:     for (final CurrencyModel currency in _currencies) {
81:       items.add(CurrencyCard(model: currency));
82:     }
83: 
84:     if (_newsItems.isNotEmpty) {
85:       items.add(
86:         Padding(
87:           padding: const EdgeInsets.only(top: 16, bottom: 4),
88:           child: Text(
89:             context.loc.news,
90:             style: context.fonts.semiBold12.copyWith(color: context.colors.tin),
91:           ),
92:         ),
93:       );
94:     }
95: 
96:     for (final NewsModel news in _newsItems) {
97:       items.add(Padding(padding: const EdgeInsets.only(top: 10), child: NewsCard(model: news)));
98:     }
99: 
100:     return items;
101:   }
102: 
103:   @override
104:   Widget build(BuildContext context) {
105:     return Scaffold(
106:       appBar: AppBar(title: Text(context.loc.dashboard)),
107:       body: FutureBuilder<void>(
108:         future: _dashboardFuture,
109:         builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
110:           if (snapshot.connectionState == ConnectionState.waiting && (_currencies.isEmpty && _newsItems.isEmpty)) {
111:             return const Center(child: CircularProgressIndicator());
112:           }
113: 
114:           if (_currencies.isEmpty && _newsItems.isEmpty && snapshot.hasError) {
115:             return const Center(child: Text('No data'));
116:           }
117: 
118:           final List<Widget> listWidgets = _buildMixedList();
119: 
120:           if (listWidgets.isEmpty) {
121:             return const Center(child: Text('No data available'));
122:           }
123: 
124:           return FadeTransition(
125:             opacity: _fadeController.view,
126:             child: ListView.builder(
127:               itemCount: listWidgets.length,
128:               itemBuilder: (BuildContext context, int index) => Padding(
129:                 key: ValueKey(index),
130:                 padding: EdgeInsets.only(top: 10, left: 22, right: 22, bottom: 10),
131:                 child: listWidgets[index],
132:               ),
133:               padding: const EdgeInsets.only(bottom: 40),
134:             ),
135:           );
136:         },
137:       ),
138:     );
139:   }
140: }

