import 'package:mad_flutter_practicum/domain/domain.dart';

class DashboardPage extends StatefulWidget {
  const DashboardPage({super.key});

  @override
  State<DashboardPage> createState() => _DashboardPageState();
}

class _DashboardPageState extends State<DashboardPage> with SingleTickerProviderStateMixin {
  late final AnimationController _fadeController;

  late Future<void> _dashboardFuture;

  List<CurrencyModel> _currencies = <CurrencyModel>[];
  List<NewsModel> _newsItems = <NewsModel>[];

  @override
  void initState() {
    super.initState();
    _initAnimation();
    _initData();
  }

  @override
  void dispose() {
    _fadeController.dispose();
    super.dispose();
  }

  void _initAnimation() {
    _fadeController = AnimationController(
      duration: const Duration(milliseconds: 400),
      vsync: this,
    );
  }

  void _initData() {
    final currencyRepository = context.read<CurrencyRepository>();
    final newsRepository = context.read<NewsRepository>();

    _dashboardFuture = Future.wait([
      currencyRepository.fetchRates(const CurrencyPageRequest()),
      newsRepository.loadNewsFeed(const NewsFeedFilter(forceRefresh: true)),
    ]).then((List<dynamic> results) {
      setState(() {
        _currencies = (results[0] as CurrencyPage).items;
        _newsItems = results[1] as List<NewsModel>;

        currencyRepository.saveCurrencyList(_currencies);
      });

      _fadeController.forward();
    }).catchError((Object error) {
      debugPrint('Dashboard load error: $error');
      setState(() {
        _currencies = <CurrencyModel>[];
        _newsItems = <NewsModel>[];
      });
    });
  }

  List<Widget> _buildMixedList() {
    final List<Widget> items = <Widget>[];

    if (_currencies.isNotEmpty) {
      items.add(
        Padding(
          padding: const EdgeInsets.only(top: 8, bottom: 4),
          child: Text(
            context.loc.currencies,
            style: context.fonts.semiBold12.copyWith(color: context.colors.tin),
          ),
        ),
      );
    }

    for (final CurrencyModel currency in _currencies) {
      items.add(CurrencyCard(model: currency));
    }

    if (_newsItems.isNotEmpty) {
      items.add(
        Padding(
          padding: const EdgeInsets.only(top: 16, bottom: 4),
          child: Text(
            context.loc.news,
            style: context.fonts.semiBold12.copyWith(color: context.colors.tin),
          ),
        ),
      );
    }

    for (final NewsModel news in _newsItems) {
      items.add(Padding(padding: const EdgeInsets.only(top: 10), child: NewsCard(model: news)));
    }

    return items;
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(context.loc.dashboard)),
      body: FutureBuilder<void>(
        future: _dashboardFuture,
        builder: (BuildContext context, AsyncSnapshot<void> snapshot) {
          if (snapshot.connectionState == ConnectionState.waiting && (_currencies.isEmpty && _newsItems.isEmpty)) {
            return const Center(child: CircularProgressIndicator());
          }

          if (_currencies.isEmpty && _newsItems.isEmpty && snapshot.hasError) {
            return const Center(child: Text('No data'));
          }

          final List<Widget> listWidgets = _buildMixedList();

          if (listWidgets.isEmpty) {
            return const Center(child: Text('No data available'));
          }

          return FadeTransition(
            opacity: _fadeController.view,
            child: ListView.builder(
              itemCount: listWidgets.length,
              itemBuilder: (BuildContext context, int index) => Padding(
                key: ValueKey(index),
                padding: EdgeInsets.only(top: 10, left: 22, right: 22, bottom: 10),
                child: listWidgets[index],
              ),
              padding: const EdgeInsets.only(bottom: 40),
            ),
          );
        },
      ),
    );
  }
}
