{"content":"import 'package:flutter_test/flutter_test.dart';
import 'package:mad_flutter_practicum/app/app.dart';
import 'package:mad_flutter_practicum/domain/domain.dart';
import 'package:mockito/mockito.dart';

import '../mocks/repository.mocks.dart';

import 'widget.dart';

void main() {
  group('DashboardPage', () {
    final MockCurrencyRepository mockCurrencyRepository = MockCurrencyRepository();
    final MockNewsRepository mockNewsRepository = MockNewsRepository();

    late List<CurrencyModel> currencyModels;
    late List<NewsModel> newsModels;

    setUp(() {
      currencyModels = <CurrencyModel>[
        CurrencyModel(
          id: '1',
          nominal: 1,
          name: 'Euro',
          symbol: '\u{20AC}',
          value: 90.0,
          previousValue: 89.5,
        ),
        CurrencyModel(
          id: '2',
          nominal: 1,
          name: 'US Dollar',
          symbol: r'$',
          value: 120.0,
          previousValue: 121.0,
        ),
      ];

      newsModels = <NewsModel>[
        NewsModel(title: 'Новость 1', link: 'https://example.com/1'),
        NewsModel(title: 'Новость 2', link: 'https://example.com/2'),
      ];

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => CurrencyPage(items: currencyModels, page: 0, hasMore: false),
      );
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => newsModels);
    });

    testWidgets('should show CircularProgressIndicator while loading', (WidgetTester tester) async {
      final Future<CurrencyPage> slowRates = Future.delayed(
        const Duration(seconds: 10),
        () => CurrencyPage(items: currencyModels, page: 0, hasMore: false),
      );
      final Future<List<NewsModel>> slowNews = Future.delayed(
        const Duration(seconds: 10),
        () => newsModels,
      );

      when(mockCurrencyRepository.fetchRates(any)).thenReturn(slowRates);
      when(mockNewsRepository.loadNewsFeed(any)).thenReturn(slowNews);

      await tester.pumpWidget(
        buildWidget(
          providers: <Provider>[
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        ),
      );

      expect(find.byType(CircularProgressIndicator), findsOneWidget);
    });

    testWidgets('should display currency cards and news after loading', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: <Provider>[
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.text('Euro'), findsOneWidget);
      expect(find.text('US Dollar'), findsOneWidget);
      expect(find.byType(CurrencyCard), findsNWidgets(2));
      expect(find.text('\u{20AC}'), findsOneWidget);
      expect(r'$', findsOneWidget);
      expect(find.text('Новость 1'), findsOneWidget);
      expect(find.text('Новость 2'), findsOneWidget);
      expect(find.byType(NewsCard), findsNWidgets(2));
    });

    testWidgets('should display dashboard title bar', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: <Provider>[
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        ),
      );

      await tester.pumpAndSettle();

      expect(find.byType(AppBar), findsOneWidget);
    });

    testWidgets('should show empty state when both data sources return empty', (WidgetTester tester) async {
      final List<CurrencyModel> emptyCurrency = <CurrencyModel>[];
      final List<NewsModel> emptyNews = <NewsModel>[];

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => CurrencyPage(items: emptyCurrency, page: 0, hasMore: false),
      );
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => emptyNews);

      await tester.pumpWidget(
        buildWidget(
          providers: <Provider>[
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
