Future<void> main() async {
  group('DashboardPage', () {
    late MockCurrencyRepository mockCurrencyRepository;
    late MockNewsRepository mockNewsRepository;

    setUp(() {
      mockCurrencyRepository = MockCurrencyRepository();
      mockNewsRepository = MockNewsRepository();
      when(mockCurrencyRepository.fetchRates(any)).thenAnswer(
        (_) async => CurrencyPage(
          items: <CurrencyModel>[
            CurrencyModel(id: '1', nominal: 1, name: 'Euro', symbol: 'EU', value: 90.0, previousValue: 89.5),
            CurrencyModel(id: '2', nominal: 1, name: 'US Dollar', symbol: 'US', value: 120.0, previousValue: 121.0),
          ],
          page: 0,
          hasMore: false,
        ),
      );
      when(mockCurrencyRepository.saveCurrencyList(any)).thenAnswer((_) async {});
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer(
        (_) async => <NewsModel>[
          NewsModel(title: '\u{41D}овость 1', link: 'https://example.com/1'),
          NewsModel(title: '\u{41D}овость 2', link: 'https://example.com/2'),
        ],
      );
    });

    testWidgets('should show CircularProgressIndicator while loading', (WidgetTester tester) async {
      final Completer<void> completer = Completer<void>();

      when(mockCurrencyRepository.fetchRates(any)).thenAnswer((_) async => completer.future.then(
            (_) => CurrencyPage(
              items: <CurrencyModel>[
                CurrencyModel(id: '1', nominal: 1, name: 'Euro', symbol: 'EU', value: 90.0, previousValue: 89.5),
              ],
              page: 0,
              hasMore: false,
            ),
          ));
      when(mockNewsRepository.loadNewsFeed(any)).thenAnswer((_) async => completer.future.then(
            (_) => <NewsModel>[NewsModel(title: '\u{41D}овость', link: 'https://example.com/1')],
          ));

      await tester.pumpWidget(
        buildWidget(
          providers: <Provider>[
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        ),
      );

      // Пока Future не завершён — показывается индикатор
      expect(find.byType(CircularProgressIndicator), findsOneWidget);
      expect(find.text('Euro'), findsNothing);

      // Разрешаем Future
      completer.complete();
      await tester.pumpAndSettle();

      // Теперь данные должны быть видны
      expect(find.text('Euro'), findsOneWidget);
      expect(find.byType(CircularProgressIndicator), findsNothing);
    });

    testWidgets('should display currency cards and news after loading', (WidgetTester tester) async {
      await tester.pumpWidget(
        buildWidget(
          providers: <Provider>[
            Provider<CurrencyRepository>.value(value: mockCurrencyRepository),
            Provider<NewsRepository>.value(value: mockNewsRepository),
          ],
          child: const DashboardPage(),
        ),
      );

      await tester.pumpAndSettle();

